DELIMITER $$
CREATE TRIGGER `log_hapus_produk` AFTER DELETE ON `produk_ternak` FOR EACH ROW BEGIN
    INSERT INTO log_produk (aksi, id_produk, nama_produk_log, keterangan)
    VALUES ('HAPUS', OLD.id, OLD.nama, CONCAT('Menghapus produk: ', OLD.nama));
END
$$
DELIMITER ;
DELIMITER $$
CREATE TRIGGER `log_tambah_produk` AFTER INSERT ON `produk_ternak` FOR EACH ROW BEGIN
    INSERT INTO log_produk (aksi, id_produk, nama_produk_log, keterangan)
    VALUES ('TAMBAH', NEW.id, NEW.nama, CONCAT('Menambahkan produk baru: ', NEW.nama));
END
$$
DELIMITER ;
DELIMITER $$
CREATE TRIGGER `log_ubah_produk` AFTER UPDATE ON `produk_ternak` FOR EACH ROW BEGIN
    -- 1. Cek Perubahan Nama
    IF OLD.nama <> NEW.nama THEN
        INSERT INTO log_produk (aksi, id_produk, nama_produk_log, keterangan)
        VALUES ('UPDATE', NEW.id, NEW.nama, CONCAT('Nama produk diganti: ', OLD.nama, ' -> ', NEW.nama));
    END IF;

    -- 2. Cek Perubahan Harga
    IF OLD.harga <> NEW.harga THEN
        INSERT INTO log_produk (aksi, id_produk, nama_produk_log, keterangan)
        VALUES ('UPDATE', NEW.id, NEW.nama, CONCAT('Harga berubah: Rp', OLD.harga, ' -> Rp', NEW.harga));
    END IF;

    -- 3. Cek Perubahan Stok
    IF OLD.stok <> NEW.stok THEN
        INSERT INTO log_produk (aksi, id_produk, nama_produk_log, keterangan)
        VALUES ('UPDATE', NEW.id, NEW.nama, CONCAT('Stok diupdate: ', OLD.stok, ' -> ', NEW.stok));
    END IF;

    -- 4. Cek Perubahan Kategori
    IF OLD.kategori <> NEW.kategori THEN
        INSERT INTO log_produk (aksi, id_produk, nama_produk_log, keterangan)
        VALUES ('UPDATE', NEW.id, NEW.nama, CONCAT('Kategori pindah: ', OLD.kategori, ' -> ', NEW.kategori));
    END IF;

    -- 5. Cek Perubahan Deskripsi
    IF OLD.deskripsi <> NEW.deskripsi THEN
        INSERT INTO log_produk (aksi, id_produk, nama_produk_log, keterangan)
        VALUES ('UPDATE', NEW.id, NEW.nama, 'Deskripsi produk telah diperbarui');
    END IF;
END
$$
DELIMITER ;

